import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> fullJustify(String[] words, int maxWidth) {
        List<String> result = new ArrayList<>();
        int start = 0;

        while (start < words.length) {
            int end = start;
            int letters = 0;
            while (end < words.length
                    && letters + words[end].length() + (end - start) <= maxWidth) {
                letters += words[end].length();
                end++;
            }

            int wordCount = end - start;
            int gaps = wordCount - 1;
            int spaces = maxWidth - letters;
            String line = "";
            for (int index = start; index < end; index++) {
                line = line + words[index];
                if (index < end - 1) {
                    int gapSpaces;
                    if (gaps == 0 || end == words.length) {
                        gapSpaces = 1;
                    } else {
                        gapSpaces = spaces / gaps;
                        if (index - start < spaces % gaps) {
                            gapSpaces++;
                        }
                    }
                    for (int count = 0; count < gapSpaces; count++) {
                        line = line + " ";
                    }
                }
            }
            while (line.length() < maxWidth) {
                line = line + " ";
            }
            result.add(line);
            start = end;
        }
        return result;
    }
}

