import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> fullJustify(String[] words, int maxWidth) {
        List<String> result = new ArrayList<>();
        int start = 0;

        while (start < words.length) {
            int end = start;
            int letters = 0;
            while (end < words.length
                    && letters + words[end].length() + (end - start) <= maxWidth) {
                letters += words[end].length();
                end++;
            }

            int wordCount = end - start;
            int gaps = wordCount - 1;
            int spaces = maxWidth - letters;
            StringBuilder line = new StringBuilder(maxWidth);

            if (gaps == 0 || end == words.length) {
                for (int index = start; index < end; index++) {
                    if (index > start) {
                        line.append(' ');
                    }
                    line.append(words[index]);
                }
                while (line.length() < maxWidth) {
                    line.append(' ');
                }
            } else {
                int spacesPerGap = spaces / gaps;
                int extraSpaces = spaces % gaps;
                for (int index = start; index < end; index++) {
                    line.append(words[index]);
                    if (index < end - 1) {
                        int gapWidth = spacesPerGap
                                + (index - start < extraSpaces ? 1 : 0);
                        for (int count = 0; count < gapWidth; count++) {
                            line.append(' ');
                        }
                    }
                }
            }

            result.add(line.toString());
            start = end;
        }
        return result;
    }
}
